UPDATE member 
SET pass = #{pass}, name = #{name}, phone = #{phone}, email = #{email}, 
    zipcode = #{zipcode}, address1 = #{address1}, address2 = #{address2} 
WHERE id = #{id}

UPDATE member 
SET money = money - #{money} 
WHERE id = #{id}

UPDATE member 
SET money = money + #{money} 
WHERE id = #{id}
